import sys
from collections import deque

def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())

    graph = [[] for _ in range(N)]
    max_z = 0

    for _ in range(M):
        x, y, z = map(int, input().split())
        x -= 1
        y -= 1
        max_z = max(max_z, z)
        graph[x].append((y, z))
        graph[y].append((x, z))

    potential = [-1] * N
    answer = [0] * N
    bit_count = max(1, max_z.bit_length())

    for start in range(N):
        if potential[start] != -1:
            continue

        potential[start] = 0
        q = deque([start])
        component = [start]

        while q:
            u = q.popleft()
            for v, z in graph[u]:
                expected = potential[u] ^ z
                if potential[v] == -1:
                    potential[v] = expected
                    component.append(v)
                    q.append(v)
                elif potential[v] != expected:
                    print(-1)
                    return

        size = len(component)
        base = 0

        for b in range(bit_count):
            ones = sum((potential[v] >> b) & 1 for v in component)
            if ones > size - ones:
                base |= 1 << b

        for v in component:
            answer[v] = potential[v] ^ base

    print(*answer)

if __name__ == "__main__":
    main()
